-- ============================================================
-- AI Resume Reviews table
-- Stores student resume critique reports generated by Groq.
-- ============================================================

create table if not exists public.ai_resume_reviews (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references public.profiles on delete cascade,
  resume_title text not null default 'Resume Review',
  review_data jsonb not null, 
  created_at timestamptz not null default now()
);

alter table public.ai_resume_reviews enable row level security;

drop policy if exists "student manages own resume reviews" on public.ai_resume_reviews;
create policy "student manages own resume reviews" on public.ai_resume_reviews for all 
  using (student_id = auth.uid()) 
  with check (student_id = auth.uid());

drop policy if exists "admin/faculty reads resume reviews" on public.ai_resume_reviews;
create policy "admin/faculty reads resume reviews" on public.ai_resume_reviews for select 
  using (public.is_admin() or public.current_role_is('faculty'));
